/* Builds src/components/session/terminalPage.generated.ts: the one HTML page the phone's session
 * terminal loads into its WebView, with xterm.js, its stylesheet and terminal-page.js inlined, so
 * the page needs no network and the app needs no new dependency (xterm is the web app's copy).
 *
 *   node apps/mobile/scripts/build-terminal-page.js
 *
 * Run it after @xterm/xterm or terminal-page.js changes; terminalPage.test.ts fails until the
 * checked-in file matches. Deliberately not a package.json script: @expo/fingerprint hashes those. */
/* global __dirname */
const fs = require("fs");
const path = require("path");

const xterm = path.dirname(require.resolve("@xterm/xterm/package.json", { paths: [path.join(__dirname, "../../frontend")] }));
const read = (...parts) => fs.readFileSync(path.join(...parts), "utf8");
// A closing tag inside a script would end it early.
const inline = (js) => js.replace(/<\/script/gi, "<\\/script").replace(/\/\/# sourceMappingURL=.*$/m, "");

function build() {
  const { version } = JSON.parse(read(xterm, "package.json"));
  const html = `<!doctype html>
<html>
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1, minimum-scale=1, maximum-scale=6, user-scalable=yes, viewport-fit=cover">
<meta http-equiv="Content-Security-Policy" content="default-src 'none'; script-src 'unsafe-inline'; style-src 'unsafe-inline'">
<style>${read(xterm, "css/xterm.css")}</style>
<style>
html, body { margin: 0; height: 100%; background: #16161a; -webkit-text-size-adjust: 100%; }
#box { position: absolute; inset: 0; overflow: auto; -webkit-overflow-scrolling: auto; -webkit-user-select: none; -webkit-touch-callout: none; }
/* Typing still needs a selectable field, and iOS zooms the page in on a focused field under 16px. */
.xterm .xterm-helper-textarea { -webkit-user-select: text; font-size: 16px !important; }
#wrap { overflow: hidden; }
#host { transform-origin: top left; }
</style>
</head>
<body>
<div id="box"><div id="wrap"><div id="host"></div></div></div>
<script>${inline(read(xterm, "lib/xterm.js"))}</script>
<script>${inline(read(__dirname, "terminal-page.js"))}</script>
</body>
</html>
`;
  return `// GENERATED by apps/mobile/scripts/build-terminal-page.js. Do not edit: run the script.
export const XTERM_VERSION = ${JSON.stringify(version)};
export const TERMINAL_HTML = ${JSON.stringify(html)};
`;
}

module.exports = { build };

if (require.main === module) {
  const out = path.join(__dirname, "../src/components/session/terminalPage.generated.ts");
  fs.writeFileSync(out, build());
  console.log(`wrote ${path.relative(process.cwd(), out)}`);
}
